import fs from 'node:fs';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {createPublicClient,http,keccak256,formatEther,getContractAddress} from '../enclave/node_modules/viem/_esm/index.js';
import {createQuorumReader} from '../enclave/custody/v2/quorum.mjs';
const require=createRequire(new URL('../enclave/package.json',import.meta.url));
const official=new URL('../compiler-review/official-soljson.js',import.meta.url),compilerHash=createHash('sha256').update(fs.readFileSync(official)).digest('hex');
if(compilerHash!=='ecabf2b0bf0c3ab0c6bb9cebd309900bd3b5e80c833d2bc68a330fa5508398f5')throw Error('compiler pin');
const solc=require('solc/wrapper')(require(official.pathname));
const content=fs.readFileSync(new URL('../enclave/contracts/EnclaveServiceIndex.sol',import.meta.url),'utf8');
const input={language:'Solidity',sources:{'contracts/EnclaveServiceIndex.sol':{content}},settings:{viaIR:true,optimizer:{enabled:true,runs:200},outputSelection:{'*':{'*':['abi','evm.bytecode.object','evm.deployedBytecode.object']}}}};
const output=JSON.parse(solc.compile(JSON.stringify(input)));if(output.errors?.some(e=>e.severity==='error'))throw Error('compiler errors');
const c=output.contracts['contracts/EnclaveServiceIndex.sol'].EnclaveServiceIndex;
const artifact={compiler:solc.version(),compilerSha256:compilerHash,sourceSha256:createHash('sha256').update(content).digest('hex'),sourceCommit:'61c16967',settings:input.settings,abi:c.abi,bytecode:'0x'+c.evm.bytecode.object,runtime:'0x'+c.evm.deployedBytecode.object};artifact.codeHash=keccak256(artifact.runtime);
fs.writeFileSync(new URL('./artifact.json',import.meta.url),JSON.stringify(artifact,null,2)+'\n');
const old=JSON.parse(fs.readFileSync(new URL('../independent-authority-deploy/costs.json',import.meta.url)));const address=old.deployer;
const urls=['https://mainnet.base.org','https://base-rpc.publicnode.com','https://base.drpc.org','https://base.public.blockpi.network/v1/rpc/public'];
const clients=urls.map(url=>createPublicClient({transport:http(url,{timeout:12000,retryCount:0})}));const q=createQuorumReader({clients,minAgree:3,chainId:8453,confirmations:2,timeoutMs:20000});
const state=await q(async(c,b)=>({nonce:await c.getTransactionCount({address,blockNumber:b.blockNumber}),balance:await c.getBalance({address,blockNumber:b.blockNumber})}));
const target=getContractAddress({from:address,nonce:BigInt(state.nonce)});
const gas=await clients[0].estimateGas({account:address,data:artifact.bytecode}),fee=await clients[0].getGasPrice();
const estimate={at:new Date().toISOString(),chainId:8453,deployer:address,funder:old.funder,target,nonce:state.nonce,balanceWei:String(state.balance),balanceETH:formatEther(state.balance),blockNumber:String(state.blockNumber),blockHash:state.blockHash,codeHash:artifact.codeHash,runtimeBytes:(artifact.runtime.length-2)/2,gasEstimate:String(gas),gasPriceWei:String(fee),estimatedExecutionETH:formatEther(gas*fee),maximumFundingETH:'0.00005',maximumFeePerGasWei:'12000000',maximumPriorityFeePerGasWei:'1000000',status:'read-only preflight; not funded or deployed'};
fs.writeFileSync(new URL('./preflight.json',import.meta.url),JSON.stringify(estimate,null,2)+'\n');console.log(JSON.stringify(estimate,null,2));
